    return [
      payloadId,
      status,
      bytesTransferred,
      totalBytes,
    ]
  }
  static func == (lhs: TransferUpdate, rhs: TransferUpdate) -> Bool {
    if Swift.type(of: lhs) != Swift.type(of: rhs) {
      return false
    }
    return MessagesPigeonInternal.deepEquals(lhs.payloadId, rhs.payloadId) && MessagesPigeonInternal.deepEquals(lhs.status, rhs.status) && MessagesPigeonInternal.deepEquals(lhs.bytesTransferred, rhs.bytesTransferred) && MessagesPigeonInternal.deepEquals(lhs.totalBytes, rhs.totalBytes)
  }

  func hash(into hasher: inout Hasher) {
    hasher.combine("TransferUpdate")
    MessagesPigeonInternal.deepHash(value: payloadId, hasher: &hasher)
    MessagesPigeonInternal.deepHash(value: status, hasher: &hasher)
    MessagesPigeonInternal.deepHash(value: bytesTransferred, hasher: &hasher)
    MessagesPigeonInternal.deepHash(value: totalBytes, hasher: &hasher)
  }

  public var description: String {
    return "TransferUpdate(payloadId: \(String(describing: payloadId)), status: \(String(describing: status)), bytesTransferred: \(String(describing: bytesTransferred)), totalBytes: \(String(describing: totalBytes)))"
  }
}

